import path from 'node:path';
export function loadConfig(overrides={}) {
  const config = {
    port: Number(process.env.PORT ?? 4100),
    dataDir: process.env.CREW_DATA_DIR ?? './data',
    secret: process.env.CREW_SECRET ?? 'local-development-change-this-secret',
    maxUploadBytes: Number(process.env.CREW_MAX_UPLOAD_BYTES ?? 25*1024*1024),
    baseUrl: process.env.CREW_BASE_URL ?? 'http://localhost:4100',
    sessionDays: 14,
    ...overrides
  };
  if(!Number.isInteger(config.port)||config.port<0||config.port>65535)throw new Error('Invalid PORT');
  if(!Number.isSafeInteger(config.maxUploadBytes)||config.maxUploadBytes<1)throw new Error('Invalid CREW_MAX_UPLOAD_BYTES');
  if(typeof config.dataDir!=='string'||!config.dataDir||config.dataDir.includes('\0'))throw new Error('Invalid CREW_DATA_DIR');
  config.dataDir=path.resolve(config.dataDir);
  if(typeof config.secret!=='string'||!config.secret.length)throw new Error('Invalid CREW_SECRET');
  if(!Number.isSafeInteger(config.sessionDays)||config.sessionDays<1||!Number.isFinite(new Date(Date.now()+config.sessionDays*86400000).getTime()))throw new Error('Invalid session lifetime');
  if(typeof config.baseUrl!=='string'||!/^https?:\/\//i.test(config.baseUrl)||/[\u0000-\u0020\u007f]/.test(config.baseUrl))throw new Error('Invalid CREW_BASE_URL');
  let base;
  try{base=new URL(config.baseUrl);}catch{throw new Error('Invalid CREW_BASE_URL');}
  if(!['http:','https:'].includes(base.protocol)||base.username||base.password||base.search||base.hash)throw new Error('Invalid CREW_BASE_URL');
  config.baseUrl=base.href.replace(/\/$/,'');
  return config;
}

import {startApplication} from './lifecycle.js';
let application;
try{
  application=await startApplication();
  console.log(JSON.stringify({ready:true,port:application.address.port,pid:process.pid}));
}catch(error){console.error(error);process.exitCode=1;}
if(application){
  let stopRequested=false;
  async function stop(reason,failure){
    if(stopRequested)return;
    stopRequested=true;
    if(failure)console.error(failure);
    const result=await application.stop(reason);
    for(const error of result.errors)console.error(error);
    console.log(JSON.stringify({stopped:true,reason:result.reason,forced:result.forced}));
    process.exitCode=failure?1:result.code;
    process.removeListener('SIGTERM',terminate);process.removeListener('SIGINT',interrupt);
    process.removeListener('uncaughtException',exception);process.removeListener('unhandledRejection',rejection);
  }
  const terminate=()=>{void stop('SIGTERM');};
  const interrupt=()=>{void stop('SIGINT');};
  const exception=error=>{void stop('uncaughtException',error);};
  const rejection=error=>{void stop('unhandledRejection',error);};
  process.on('SIGTERM',terminate);process.on('SIGINT',interrupt);
  process.once('uncaughtException',exception);process.once('unhandledRejection',rejection);
}

import {createApp} from './app.js';
export async function startApplication(overrides={},options={}) {
  const create=options.create??createApp;
  const shutdownMs=options.shutdownMs??3000;
  if(!Number.isSafeInteger(shutdownMs)||shutdownMs<1)throw new Error('Shutdown deadline must be a positive integer');
  const ctx=await create(overrides);
  let server;
  try{
    server=ctx.app.listen(ctx.config.port,options.host??'0.0.0.0');
    await new Promise((resolve,reject)=>{
      const failed=error=>{server.removeListener('listening',ready);reject(error);};
      const ready=()=>{server.removeListener('error',failed);resolve();};
      server.once('error',failed);server.once('listening',ready);
    });
  }catch(error){
    try{ctx.close();}catch(cleanup){throw new AggregateError([error,cleanup],'Crew startup and cleanup failed',{cause:error});}
    throw error;
  }
  let stopping=false,finished=false,deadline;
  const errors=[];
  let resolveClosed;
  const closed=new Promise(resolve=>{resolveClosed=resolve;});
  function finish(reason,forced) {
    if(finished)return;
    finished=true;clearTimeout(deadline);
    try{ctx.close();}catch(error){errors.push(error);}
    resolveClosed({reason,forced,errors,code:forced||errors.length?1:0});
  }
  function stop(reason='shutdown') {
    if(stopping)return closed;
    stopping=true;
    try{ctx.cleanup();}catch(error){errors.push(error);}
    deadline=setTimeout(()=>{
      try{server.closeAllConnections();}catch(error){errors.push(error);}
      finish(reason,true);
    },shutdownMs);
    try{
      server.close(error=>{
        if(error&&error.code!=='ERR_SERVER_NOT_RUNNING')errors.push(error);
        finish(reason,false);
      });
      server.closeIdleConnections();
    }catch(error){errors.push(error);server.closeAllConnections();finish(reason,true);}
    return closed;
  }
  return {ctx,server,stop,closed,address:server.address()};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import net from 'node:net';
import {once} from 'node:events';
import {startApplication} from '../src/lifecycle.js';
import {loadConfig} from '../src/config.js';
import {createApp} from '../src/app.js';
async function folder(){return mkdtemp(path.join(tmpdir(),'crew-runtime-'));}
test('runtime binds an actual ephemeral port and closes once after cleanup',async()=>{
  const dataDir=await folder();let application;
  try{
    application=await startApplication({port:0,dataDir,secret:'runtime-secret'},{host:'127.0.0.1'});
    assert(application.address.port>0);assert.equal((await fetch('http://127.0.0.1:'+application.address.port+'/api/v1/health')).status,200);
    const first=application.stop('first'),second=application.stop('second');assert.equal(first,second);
    const result=await first;assert.equal(result.reason,'first');assert.equal(result.forced,false);assert.equal(result.code,0);
    assert.throws(()=>application.ctx.db.prepare('SELECT 1'),/closed|not open/i);
  }finally{if(application)await application.stop();await rm(dataDir,{recursive:true,force:true});}
});
test('bind failure closes the actual created database and event listeners',async()=>{
  const dataDir=await folder(),occupied=net.createServer();occupied.listen(0,'127.0.0.1');await once(occupied,'listening');let ctx;
  try{
    await assert.rejects(startApplication({port:occupied.address().port,dataDir},{host:'127.0.0.1',create:async options=>{ctx=await createApp(options);return ctx;}}),error=>error.code==='EADDRINUSE');
    assert.throws(()=>ctx.db.prepare('SELECT 1'),/closed|not open/i);assert.equal(ctx.bus.listenerCount,0);
  }finally{await new Promise(resolve=>occupied.close(resolve));await rm(dataDir,{recursive:true,force:true});}
});
test('shutdown deadline drains a stalled real request and reports forced cleanup',async()=>{
  const dataDir=await folder();let application,socket;
  try{
    application=await startApplication({port:0,dataDir},{host:'127.0.0.1',shutdownMs:40});
    socket=net.connect(application.address.port,'127.0.0.1');await once(socket,'connect');const receiving=once(application.server,'request');socket.write('POST /api/v1/auth/login HTTP/1.1\r\nHost: localhost\r\nContent-Length: 999\r\nContent-Type: application/json\r\n\r\n{');
    await receiving;const result=await application.stop('deadline');assert.equal(result.forced,true);assert.equal(result.code,1);assert.throws(()=>application.ctx.db.prepare('SELECT 1'),/closed|not open/i);
  }finally{socket?.destroy();if(application)await application.stop();await rm(dataDir,{recursive:true,force:true});}
});
test('a cleanup failure does not skip later registered cleanup or database closure',async()=>{
  const dataDir=await folder();let application;let released=0;
  try{
    application=await startApplication({port:0,dataDir},{host:'127.0.0.1',create:async options=>{const ctx=await createApp(options);ctx.cleanups.push(()=>{throw new Error('controlled cleanup failure');},()=>released++);return ctx;}});
    const result=await application.stop();assert.equal(released,1);assert.equal(result.code,1);assert.equal(result.errors.length,1);assert.equal(result.forced,false);
    assert.throws(()=>application.ctx.db.prepare('SELECT 1'),/closed|not open/i);
  }finally{if(application)await application.stop();await rm(dataDir,{recursive:true,force:true});}
});
test('configuration rejects invalid origin credentials paths and session lifetimes before startup',()=>{
  for(const overrides of [{baseUrl:'https://u:p@host'},{baseUrl:'https://host/?secret=bad'},{baseUrl:'http:host'},{baseUrl:'https://host/#fragment'},{baseUrl:'https://host/\n'},{dataDir:''},{dataDir:null},{dataDir:'bad\0path'},{sessionDays:0},{sessionDays:Number.MAX_SAFE_INTEGER}])assert.throws(()=>loadConfig(overrides));
  const config=loadConfig({baseUrl:'https://crew.example.test/',dataDir:'./data',sessionDays:14});assert.equal(config.baseUrl,'https://crew.example.test');assert(path.isAbsolute(config.dataDir));
});

import json,sys,tempfile
from selenium import webdriver
from selenium.webdriver.chrome.service import Service
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.support.ui import WebDriverWait
settings=json.loads(sys.argv[1]);flags={}
options=webdriver.ChromeOptions()
options.binary_location='/usr/bin/chromium'
for value in ['--headless=new','--no-sandbox','--disable-dev-shm-usage','--window-size=1280,1000']: options.add_argument(value)
with tempfile.TemporaryDirectory(prefix='crew-shell-browser-') as profile:
    options.add_argument('--user-data-dir='+profile)
    driver=webdriver.Chrome(service=Service('/usr/bin/chromedriver'),options=options)
    driver.set_page_load_timeout(10)
    wait=WebDriverWait(driver,8)
    def heading(text): return wait.until(lambda d: any(text in node.text for node in d.find_elements(By.TAG_NAME,'h1')))
    def fill(name,value):
        element=wait.until(lambda d:d.find_element(By.NAME,name));element.send_keys(Keys.CONTROL,'a',Keys.NULL,Keys.BACKSPACE);element.send_keys(value)
    def button(text): return wait.until(lambda d:d.find_element(By.XPATH,"//button[normalize-space()="+json.dumps(text)+"]"))
    def link(text): return wait.until(lambda d:d.find_element(By.LINK_TEXT,text))
    def login(password='correct shell password'):
        fill('email','shell-owner@example.test');fill('password',password);button('Sign in').click()
    try:
        driver.get(settings['url']+'/');heading('Welcome back')
        driver.execute_cdp_cmd('Page.addScriptToEvaluateOnNewDocument',{'source':"""
          const originalFetch=window.fetch.bind(window);
          window.__failMe=sessionStorage.getItem('shellFailMe')==='yes';
          window.fetch=async (...args)=>{
            const url=String(args[0]);
            if(window.__failMe&&url.endsWith('/me'))throw new TypeError('controlled initial network failure');
            const response=await originalFetch(...args);
            if(window.__holdLogin&&url.endsWith('/auth/login')){
              window.__held=true;await new Promise(resolve=>window.__releaseLogin=resolve);window.__settled=true;
            }
            return response;
          };
        """})
        driver.get(settings['url']+'/#/issues/'+settings['issueId']);heading('Welcome back')
        login('incorrect password')
        wait.until(lambda d: 'Email or password' in d.find_element(By.CSS_SELECTOR,'.notice.error').text)
        assert driver.find_element(By.NAME,'email').get_attribute('value')=='shell-owner@example.test';flags['wrongPasswordCustody']=True
        fill('password','correct shell password');button('Show password').click()
        assert driver.find_element(By.NAME,'password').get_attribute('type')=='text';flags['passwordVisibility']=True
        button('Sign in').click();heading('Deep link issue');assert driver.current_url.endswith('#/issues/'+settings['issueId']);flags['deepLink']=True
        for step in range(30):
            ActionChains(driver).key_down(Keys.SHIFT).send_keys(Keys.TAB).key_up(Keys.SHIFT).perform()
            if driver.switch_to.active_element.text=='Skip to content': break
        assert driver.switch_to.active_element.text=='Skip to content'
        driver.switch_to.active_element.send_keys(Keys.ENTER);assert driver.switch_to.active_element.get_attribute('id')=='crew-content';flags['skipFocus']=True
        driver.find_element(By.CSS_SELECTOR,'a.brand').click();heading("Your team's work")
        button('Shell organization').click();wait.until(lambda d: 'Projects in Shell organization' in d.find_element(By.ID,'overview-projects').text)
        assert link('HOME · Shell project');flags['overview']=True
        button('Sign out').click();heading('Welcome back');link('Create an account').click();heading('Create your account')
        fill('name','New browser account');fill('email','new-shell@example.test');fill('password','new shell password');fill('confirmation','different shell password');button('Create account').click()
        wait.until(lambda d:'Passwords do not match' in d.find_element(By.CSS_SELECTOR,'.notice.error').text);flags['confirmation']=True
        fill('confirmation','new shell password');button('Create account').click();heading("Your team's work")
        assert 'New browser account' in driver.find_element(By.TAG_NAME,'footer').text;flags['signup']=True
        button('Sign out').click();heading('Welcome back');driver.execute_script('window.__holdLogin=true');login()
        wait.until(lambda d:d.execute_script('return window.__held===true'));link('Create an account').click();heading('Create your account');fill('name','Retained draft')
        driver.execute_script('window.__releaseLogin()');wait.until(lambda d:d.execute_script('return window.__settled===true'))
        driver.execute_async_script('const done=arguments[0];requestAnimationFrame(()=>requestAnimationFrame(done));')
        assert driver.find_element(By.NAME,'name').get_attribute('value')=='Retained draft';assert not driver.find_elements(By.CSS_SELECTOR,'nav[aria-label="Main navigation"]');flags['abandonedForm']=True
        driver.execute_script("sessionStorage.setItem('shellFailMe','yes')");driver.refresh();heading('Crew could not check your session');flags['startupFailure']=True
        driver.execute_script("window.__failMe=false;sessionStorage.removeItem('shellFailMe')");button('Check session again').click()
        wait.until(lambda d:d.find_elements(By.CSS_SELECTOR,'nav[aria-label="Main navigation"]'));assert 'Shell Owner' in driver.find_element(By.TAG_NAME,'footer').text;flags['explicitRecovery']=True
        print(json.dumps(flags))
    finally: driver.quit()
